import unittest

from hourglass.errors import ProjectError
from hourglass.models import Shift, Span
from hourglass.timesheet import timesheet_lines


def shift(worker, start, end, day="mon"):
    return Shift(worker, day, Span(start, end))


class TimesheetTests(unittest.TestCase):
    def test_busiest_first_with_one_decimal(self):
        shifts = [shift("Ann", 480, 540), shift("Bo", 480, 750), shift("Bo", 480, 600, "tue")]
        self.assertEqual(timesheet_lines(shifts), ["Bo: 2 shifts, 6.5 hours", "Ann: 1 shift, 1.0 hours"])

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            timesheet_lines([])

    def test_blank_worker_raises(self):
        with self.assertRaises(ProjectError):
            timesheet_lines([shift("  ", 480, 540)])
